class TestThreadSafety:
    """Test thread safety of the RateLimiter."""

    def test_concurrent_requests(self, rate_limiter_strict):
        """Test that concurrent requests are handled safely."""
        errors: List[Exception] = []
        results: List[bool] = []
        lock = threading.Lock()
        
        def make_request():
            try:
                result = rate_limiter_strict.is_allowed("agent_1")
                with lock:
                    results.append(result)
            except Exception as e:
                with lock:
                    errors.append(e)
        
        threads = [threading.Thread(target=make_request) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        
        assert len(errors) == 0
        # With limit of 3, only 3 should be allowed
        assert sum(results) == 3

    def test_concurrent_different_agents(self, rate_limiter_strict):
        """Test concurrent requests from different agents."""
        errors: List[Exception] = []
        results: List[Tuple[str, bool]] = []
        lock = threading.Lock()
        
        def make_request(agent_id: str):
            try:
                result = rate_limiter_strict.is_allowed(agent_id)
                with lock:
                    results.append((agent_id, result))
            except Exception as e:
                with lock:
                    errors.append(e)
        
        agents = ["agent_1", "agent_2", "agent_3"]
        threads = []
        for agent in agents:
            for _ in range(5):
                t = threading.Thread(target=make_request, args=(agent,))
                threads.append(t)
        
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        
        assert len(errors) == 0
        # Each agent should have exactly 3 allowed requests
        for agent in agents:
            agent_results = [r for a, r in results if a == agent]
            assert sum(agent_results) == 3

    def test_concurrent_reset(self, rate_limiter_strict):
        """Test concurrent reset operations."""
        errors: List[Exception] = []
        lock = threading.Lock()
        
        def reset_agent(agent_id: str):
            try:
                rate_limiter_strict.reset(agent_id)
            except Exception as e:
                with lock:
                    errors.append(e)
        
        # First, make some requests
        for _ in range(3):
            rate_limiter_strict.is_allowed("agent_1")
        
        # Concurrently reset and check
        threads = [
            threading.Thread(target=reset_agent, args=("agent_1",)),
            threading.Thread(target=lambda: rate_limiter_strict.is_allowed("agent_1")),
            threading.Thread(target=reset_agent, args=("agent_2",)),
        ]
        
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        
        assert len(errors) == 0

    def test_concurrent_check_limit(self, rate_limiter_strict):
        """Test concurrent check_limit operations."""
        errors: List[Exception] = []
        lock = threading.Lock()
        
        def check_limit():
            try:
                rate_limiter_strict.check_limit("agent_1")
            except RateLimitExceeded:
                pass  # Expected for some threads
            except Exception as e:
                with lock:
                    errors.append(e)
        
        threads = [threading.Thread(target=check_limit) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        
        assert len(errors) == 0


