class TestIntegration:
    """Test integration scenarios and real-world usage patterns."""

    def test_mixed_operations(self, rate_limiter_strict):
        """Test a mix of operations."""
        # Simulate real usage pattern
        assert rate_limiter_strict.is_allowed("agent_1") is True
        assert rate_limiter_strict.get_remaining("agent_1") == 2
        
        rate_limiter_strict.check_limit("agent_1")
        assert rate_limiter_strict.get_remaining("agent_1") == 1
        
        rate_limiter_strict.is_allowed("agent_1")
        assert rate_limiter_strict.get_remaining("agent_1") == 0
        
        assert rate_limiter_strict.is_allowed("agent_1") is False
        
        rate_limiter_strict.reset("agent_1")
        assert rate_limiter_strict.get_remaining("agent_1") == 3

    def test_multiple_agents_complex(self, rate_limiter_strict):
        """Test complex interactions between multiple agents."""
        # Agent 1 uses all its quota
        for _ in range(3):
            rate_limiter_strict.is_allowed("agent_1")
        
        # Agent 2 uses part of its quota
        rate_limiter_strict.is_allowed("agent_2")
        rate_limiter_strict.is_allowed("agent_2")
        
        # Agent 3 doesn't make any requests
        assert rate_limiter_strict.get_remaining("agent_1") == 0
        assert rate_limiter_strict.get_remaining("agent_2") == 1
        assert rate_limiter_strict.get_remaining("agent_3") == 3
        
        # Agent 1 is blocked, Agent 2 can make one more, Agent 3 can make all
        assert rate_limiter_strict.is_allowed("agent_1") is False
        assert rate_limiter_strict.is_allowed("agent_2") is True
        assert rate_limiter_strict.is_allowed("agent_3") is True

    def test_window_sliding_complex(self, rate_limiter_strict):
        """Test complex window sliding behavior."""
        # Make requests at different times
        rate_limiter_strict.is_allowed("agent_1")
        time.sleep(2)
        rate_limiter_strict.is_allowed("agent_1")
        time.sleep(2)
        rate_limiter_strict.is_allowed("agent_1")
        
        # Should be blocked now
        assert rate_limiter_strict.is_allowed("agent_1") is False
        
        # Wait for first request to expire (total window is 5s, first was 4s ago)
        time.sleep(1)
        # First request should have expired, so we should have 1 slot available
        assert rate_limiter_strict.is_allowed("agent_1") is True

    def test_rate_limiter_with_custom_rules(self):
        """Test rate limiter with custom rules for different endpoints."""
        limiter = RateLimiter(default_limit=100, default_window=60)
        
        # Simulate different endpoints with different limits
        api_limit = 10
        auth_limit = 3
        
        # API endpoint
        for _ in range(10):
            assert limiter.is_allowed("api_user", limit=api_limit) is True
        assert limiter.is_allowed("api_user", limit=api_limit) is False
        
        # Auth endpoint (different agent)
        for _ in range(3):
            assert limiter.is_allowed("auth_user", limit=auth_limit) is True
        assert limiter.is_allowed("auth_user", limit=auth_limit) is False


