class TestPerformance:
    """Test performance characteristics of the rate limiter."""

    def test_throughput(self, rate_limiter_default):
        """Test that rate limiter can handle high throughput."""
        start_time = time.time()
        num_requests = 10000
        
        for i in range(num_requests):
            rate_limiter_default.is_allowed(f"agent_{i % 100}")
        
        elapsed = time.time() - start_time
        requests_per_second = num_requests / elapsed
        
        # Should handle at least 10,000 requests per second
        assert requests_per_second > 10000, f"Throughput too low: {requests_per_second:.2f} req/s"

    def test_memory_usage(self, rate_limiter_default):
        """Test that memory usage doesn't grow unbounded."""
        import sys
        
        initial_size = sys.getsizeof(rate_limiter_default._windows)
        
        # Add many agents
        for i in range(1000):
            rate_limiter_default._get_window(f"agent_{i}")
        
        final_size = sys.getsizeof(rate_limiter_default._windows)
        
        # Memory should grow linearly with number of agents
        # Each deque should be relatively small
        assert final_size > initial_size
        assert final_size < initial_size + 100000  # Reasonable growth


